if not buffer then
local _b={}
local mf=math.floor
local sb=string.byte
local sc=string.char
local function _rd(b,o)
if b._s then return sb(b._s,o+1) or 0 end
return b._d[o] or 0
end
local function _wr(b,o,v)
if b._s then
local d={}
for i=0,b._size-1 do d[i]=sb(b._s,i+1) or 0 end
b._d=d;b._s=nil
end
b._d[o]=v
end
_b.create=function(sz)
local t={_size=sz,_d={}}
for i=0,sz-1 do t._d[i]=0 end
return t
end
_b.fromstring=function(s) return{_size=#s,_s=s} end
_b.tostring=function(b)
if b._s then return b._s end
local t={}
for i=0,b._size-1 do t[i+1]=sc(b._d[i] or 0) end
