_b.fill=function(b,v,f,cn)
f=f or 0;cn=cn or b._size
for i=f,f+cn-1 do _wr(b,i,v%256) end
end
_b.copy=function(dst,doff,src,soff,cn)
soff=soff or 0;cn=cn or src._size
for i=0,cn-1 do _wr(dst,doff+i,_rd(src,soff+i)) end
end
