end
return(s==0 and 1 or -1)*math.ldexp(1+m/8388608,e-127)
end
local function _wf32(b,o,v)
local u
if v~=v then u=2139095040
elseif v==math.huge then u=2139095040
elseif v==-math.huge then u=4286578688
elseif v==0 then u=0
else
local s=0
if v<0 then s=1;v=-v end
local e=math.floor(math.log(v)/math.log(2))
if e>127 then e=127 elseif e<-126 then e=-126 end
local m=v/math.ldexp(1,e)-1
m=math.floor(m*8388608+0.5)
if m>=8388608 then m=0;e=e+1 end
u=s*2147483648+(e+127)*8388608+m
end
