end
return(s==0 and 1 or -1)*math.ldexp(1+(mh*4294967296+lo)/4503599627370496,e-1023)
end
local function _wf64(b,o,v)
if v~=v then _b.writeu32(b,o,0);_b.writeu32(b,o+4,2146959360);return end
