if v==-math.huge then _b.writeu32(b,o,0);_b.writeu32(b,o+4,4293918720);return end
if v==0 then _b.writeu32(b,o,0);_b.writeu32(b,o+4,0);return end
local s=0
if v<0 then s=1;v=-v end
local e=math.floor(math.log(v)/math.log(2))
if e>1023 then e=1023 elseif e<-1022 then e=-1022 end
local m=v/math.ldexp(1,e)-1
local mh=math.floor(m*1048576)
local ml=math.floor((m*1048576-mh)*4294967296)
local hi=s*2147483648+(e+1023)*1048576+mh
_b.writeu32(b,o,ml)
