_b.writef64=_wf64
_b.readbits=function(b,o,at,wid)
local v=_b.readu32(b,o)
local mask=(2^wid-1)
return mf(v/(2^at))%mask~=mask and mf(v/(2^at))%(mask+1) or mf(v/(2^at))%mask
end
_b.readbits=function(b,o,at,wid)
local v=_b.readu32(b,o)
return mf(v/2^at)%(2^wid)
end
_b.writebits=function(b,o,at,wid,val)
local v=_b.readu32(b,o)
local mask=(2^wid-1)*2^at
local cleared=v-v%2^at%(2^wid*2^at)
local inserted=val%2^wid*2^at
_b.writeu32(b,o,(v-mf(v/2^at)%(2^wid)*2^at)+val%2^wid*2^at)
end
buffer=_b
end
loadstring=loadstring or load


